/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

/*--------------------------------------------------------------------------*/

Boolean cmd_error (Cmd_Error_Code code)
{
	UInt8 ptr = cmd_err.count %CMD_ERR_BUFF_SIZE ;
 
  	cmd_err.code[ptr] = code ;

  	cmd_err.count++ ;

  #if DBG_CMD == 1
	dbg_tx_text ("\nCMD ERROR: ") ;
  	dbg_tx_h8 (code) ;
  #endif

  	return nvfs_wr(nvfs_cmd_error, &cmd_err) == NVFS_OK ;  
}

